//! Independent scalar oracle coverage for the sixteen ODF value-inspection
//! and conversion functions.
//!
//! The expected corpus is generated by the production-free Python oracle in
//! the validation evidence tree.  Empty/reference cases remain covered by the
//! dedicated value and resource suites because this scalar target has no
//! resolver; all direct scalar observations are checked here against the
//! independent values.

use std::num::{NonZeroU64, NonZeroUsize};

use litchi_core::{
    Budget, CancellationSource, ExecutionContext, ExecutionLimits, Limits as CoreLimits, Profile,
};
use litchi_ods::codec::formula::{
    evaluation::{
        EvaluationContext, EvaluationFailure, EvaluationLimits, ScalarError, ScalarValue,
        evaluate_scalar,
        value::{self, CellRead, Context, Limits, Mode, Position, Resolver, SheetExtent, Value},
    },
    expression::Expression,
};
use serde_json::Value as JsonValue;

#[derive(Debug, PartialEq)]
enum Observed {
    Number(f64),
    Logical(bool),
    Text(String),
    Error(ScalarError),
    Other,
}

fn execution(scope: &str) -> ExecutionContext {
    let budget = Budget::root(scope.to_owned(), CoreLimits::for_profile(Profile::Server));
    let (_cancellation, token) = CancellationSource::pair();
    ExecutionContext::new(
        budget,
        token,
        ExecutionLimits::new(
            NonZeroUsize::new(1).expect("one worker"),
            NonZeroUsize::new(1).expect("one task"),
            NonZeroU64::new(1024 * 1024).expect("one MiB"),
            0,
        )
        .expect("execution limits"),
    )
}

fn observe(result: &ScalarValue<'_>) -> Observed {
    match result {
        ScalarValue::Number(value) => Observed::Number(*value),
        ScalarValue::Logical(value) => Observed::Logical(*value),
        ScalarValue::Text(value) => Observed::Text(value.to_string()),
        ScalarValue::Error(error) => Observed::Error(*error),
        ScalarValue::Complex(_) => Observed::Other,
        _ => Observed::Other,
    }
}

#[derive(Debug)]
struct NoReadResolver;

impl Resolver for NoReadResolver {
    fn sheet_extent(
        &self,
        _sheet: &str,
        _execution: &ExecutionContext,
    ) -> Result<Option<SheetExtent>, EvaluationFailure> {
        Ok(None)
    }

    fn read_cell<'a>(
        &'a self,
        _sheet: &str,
        _row: usize,
        _column: usize,
        _execution: &ExecutionContext,
    ) -> Result<CellRead<'a>, EvaluationFailure> {
        Ok(CellRead::Empty)
    }

    fn sheet_index(
        &self,
        _sheet: &str,
        _execution: &ExecutionContext,
    ) -> Result<Option<usize>, EvaluationFailure> {
        Ok(None)
    }

    fn sheet_name_at(
        &self,
        _index: usize,
        _execution: &ExecutionContext,
    ) -> Result<Option<&str>, EvaluationFailure> {
        Ok(None)
    }

    fn sheet_count(&self, _execution: &ExecutionContext) -> Result<usize, EvaluationFailure> {
        Ok(0)
    }
}

fn observe_value(result: &value::Evaluated<'_>) -> Observed {
    match result.value() {
        Value::Number(value) => Observed::Number(value),
        Value::Logical(value) => Observed::Logical(value),
        Value::Text(value) => Observed::Text(value.to_owned()),
        Value::Error(error) => Observed::Error(error),
        _ => Observed::Other,
    }
}

fn formula_error(name: &str) -> ScalarError {
    match name {
        "#NULL!" => ScalarError::Null,
        "#DIV/0!" => ScalarError::DivisionByZero,
        "#VALUE!" => ScalarError::Value,
        "#REF!" => ScalarError::Reference,
        "#NAME?" => ScalarError::Name,
        "#NUM!" => ScalarError::Number,
        "#N/A" => ScalarError::NotAvailable,
        other => panic!("unsupported formula error {other}"),
    }
}

fn expected(value: &JsonValue) -> Observed {
    match value["type"].as_str().expect("expected type") {
        "number" => Observed::Number(value["value"].as_f64().expect("expected number")),
        "logical" => Observed::Logical(value["value"].as_bool().expect("expected logical")),
        "text" => Observed::Text(value["value"].as_str().expect("expected text").to_owned()),
        "error" => Observed::Error(formula_error(
            value["value"].as_str().expect("expected error"),
        )),
        other => panic!("unsupported expected type {other}"),
    }
}

fn evaluate(source: &str, execution: &ExecutionContext) -> Result<Observed, EvaluationFailure> {
    let expression = Expression::parse(source).unwrap_or_else(|error| {
        panic!("{source:?} from independent inspection oracle should parse: {error}")
    });
    // The scalar evaluator intentionally has no Array result representation.
    // TYPE({1;2}) is a scalar-result inspection of an Array, so route that
    // resolver-free case through the value API in scalar mode.  The remaining
    // corpus stays on the established scalar path.
    if source.contains('{') {
        let resolver = NoReadResolver;
        let context = Context::new(execution, Position::new("Sheet", 0, 0)).with_mode(Mode::Scalar);
        let result = value::evaluate(&expression, &resolver, &context, &Limits::default())?;
        return Ok(observe_value(&result));
    }
    let result = evaluate_scalar(
        &expression,
        &EvaluationContext::new(execution),
        &EvaluationLimits::default(),
    )?;
    Ok(observe(result.value()))
}

#[test]
fn scalar_inspection_functions_match_independent_oracle() {
    let document: JsonValue = serde_json::from_str(include_str!(
        "../../../docs/report/spec-gap-validation-evidence/ods-formula-value-inspection/inspection-goldens.json"
    ))
    .expect("inspection oracle JSON");
    let declared_functions: std::collections::BTreeSet<_> = document["functions"]
        .as_array()
        .expect("function list")
        .iter()
        .map(|function| function.as_str().expect("function name"))
        .collect();
    assert!(
        !declared_functions.is_empty(),
        "oracle function list is empty"
    );
    let rows = document["observations"].as_array().expect("observations");
    assert!(!rows.is_empty(), "oracle observations are empty");

    let execution = execution("ods-formula-inspection-oracle");
    let mut observed_functions = std::collections::BTreeSet::new();
    for row in rows {
        // `<Empty>` is a raw input marker in the Python corpus, not formula
        // syntax.  Resolver-backed Empty and Reference behavior is asserted
        // by ods_formula_inspection_evaluation instead.
        let formula = row["formula"].as_str().expect("formula");
        if formula.contains("<Empty>") {
            continue;
        }
        observed_functions.insert(row["function"].as_str().expect("function"));
        let actual = evaluate(formula, &execution)
            .unwrap_or_else(|error| panic!("{formula} should evaluate: {error}"));
        let wanted = expected(&row["expected"]);
        match (&actual, &wanted) {
            (Observed::Number(actual), Observed::Number(wanted)) => {
                let tolerance = wanted.abs().max(1.0) * 1e-13;
                assert!(
                    (actual - wanted).abs() <= tolerance,
                    "{formula}: {actual} != {wanted}"
                );
            },
            _ => assert_eq!(actual, wanted, "{formula}"),
        }
    }
    assert_eq!(observed_functions, declared_functions);
}
